// Inspect a supplied board only; no move choice, ranking, or future search.
module.exports = function(board) {
 const cols="ABCDEFGHJ", nb=p=>{let x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};
 const seen=new Set(),groups=[],regions=[],area={X:0,O:0,neutral:0};
 for(const p of Object.keys(board)){if(seen.has(p))continue;const color=board[p],q=[p],points=[],libs=new Set(),border=new Set();seen.add(p);
 while(q.length){let u=q.pop();points.push(u);for(const v of nb(u)){if(board[v]===color&&!seen.has(v)){seen.add(v);q.push(v);}else if(board[v]!==color){if(board[v]===".")libs.add(v);else border.add(board[v]);}}}
 if(color==="."){regions.push({points,border:[...border]});if(border.size===1)area[[...border][0]]+=points.length;else area.neutral+=points.length;}else{groups.push({color,stones:points,liberties:[...libs]});area[color]+=points.length;}
 }return {groups,regions,area};
};

// Replay actual recorded moves only; no hypothetical search or recommendations.
