 const cols="ABCDEFGHJ",b={},captures={X:0,O:0},moves=[],checks=[];let ko=null,index=0;
 for(let y=1;y<=9;y++)for(const c of cols)b[c+y]=".";
 const nb=p=>{let x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};
 const group=p=>{let seen=new Set([p]),q=[p],lib=new Set();while(q.length){let u=q.pop();for(const v of nb(u)){if(b[v]===".")lib.add(v);else if(b[v]===b[p]&&!seen.has(v)){seen.add(v);q.push(v);}}}return {stones:[...seen],liberties:[...lib]};};
 for(const event of log.events){
 while(index<event.afterMove){const m=log.moves[index++],color=m.color==="B"?"X":"O",enemy=color==="X"?"O":"X",removed=[];
 if(m.move==="pass")ko=null;else{const p=m.move;if(b[p]!==".")throw Error("Occupied "+p);if(ko===p)throw Error("Ko "+p);b[p]=color;for(const v of nb(p))if(b[v]===enemy){const g=group(v);if(!g.liberties.length)for(const u of g.stones){b[u]=".";removed.push(u);}}
