 const s=event.response.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");let n=0;
 for(const line of s.split("\n")){let m=line.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((v,i)=>{const p=cols[i]+m[1];if(b[p]!==v)throw Error("Board mismatch "+p);n++;});}
 if(n!==81)throw Error("Incomplete board");
 const c=s.match(/Captured by Black: (\d+); by White: (\d+)/),k=s.match(/Ko point: ([A-HJ][1-9]|none)/),mn=s.match(/Move number: (\d+)/);
 if(!c||+c[1]!==captures.X||+c[2]!==captures.O)throw Error("Capture mismatch");
 if(!k||(k[1]==="none"?null:k[1])!==ko)throw Error("Ko mismatch");
 if(!mn||+mn[1]!==index+1)throw Error("Move number mismatch");
 checks.push({kind:event.kind,afterMove:index,boardPoints:n,captures:{...captures},ko});
 }
 if(index!==log.moves.length)throw Error("Move count mismatch");
 return {moves,checks,finalCaptures:captures,board:b,finalStones:{Black:Object.values(b).filter(v=>v==="X").length,White:Object.values(b).filter(v=>v==="O").length}};
};
